styles.css:
.wp-travel-book ,
.wp-element-button:hover,
.wp-element-button:focus,
.wpcf7-submit:hover,
.wp-block-search__button:focus,
.wp-block-search__button:hover,
.wp-block-button a:focus,
.wp-block-button a:hover,
.wp-block-button__link:hover,
.wp-block-button__link:focus {
    background-color: #FF6F3C !important;
    border: none !important;
}

.zindex-high{
z-index: 999;
}

span.wp-block-cover__background.has-black-background-color.has-background-dim {
    z-index:0;
}

.page-numbers.current,
a:focus,
a:hover {
    color: var(--wp--preset--color--secondary);
}

.wp-block-query-pagination a,
.wp-block-comment-date a,
.wp-block-comment-author-name a,
.wp-block-navigation-submenu a,
.wp-block-navigation-link a,
.wp-block-categories a,
.wp-block-post-title a,
.wp-block-site-title a {
    text-decoration: none !important;
}


.about-section-image-relative {
    z-index: 2;
    position: relative !important;
}

.testimonial-relative-post-content,
.about-relative-post-content {
    z-index: 2;
    position: relative !important;
}

.wpcf7-text {
    width: 100%;
    height: 30px;
}

.wpcf7-textarea {
    width: 100%;
}
#wp-travel-book-now ,
.wp-travel-book ,
.wp-element-button,
.wpcf7-submit,
.wp-block-button__link {
    background: #1E81B0 !important;
    border: none !important;
    color: #fff!important;
    font-size: 15px;
    border-radius: 10px !important; /* Consistent border radius */
    padding: 15px 30px !important; /* Added padding */
}
#wp-travel-book-now:hover ,
.wp-travel-book:hover ,
input.wp-element-button:hover,
.wpcf7-submit:hover,
.wp-block-button__link:hover,
input.wp-element-button:focus,
.wpcf7-submit:focus,
.wp-block-button__link:focus {
    background-color: #FF6F3C !important; /* Change background on hover/focus */
    color: #fff !important; /* Text color stays white */
    border: none !important; /* Ensure no border on hover */
}

.single .wp-block-post-terms a {
    border: 1px solid;
    border-radius: 2px;
    padding: 5px;
    margin: 5px;
    text-decoration: none;
}

@media only screen and (max-width: 1000px) {
    .mobile-disable {
        display: none;
    }
}


 .image-zoom:hover img {
transition: transform 0.3s ease-in-out;
    transform: scale(1.05); 
}
.wensa-prova-image-ani:hover {
    transform: translateY(-8px);
    transition: transform 0.5s ease;
}
.wp-block-post-template{
padding:0px 0px!important;
}

#wens-prova-category.wp-block-columns {
    display: flex;
    flex-wrap: wrap; /* Enable wrapping for columns */
    gap: 16px; /* Add space between columns */
}

@media (max-width: 781px) {
    #wens-prova-category .wp-block-column {
        flex: 1 1 calc(33.333% - 16px); /* Show 3 columns per row */
        max-width: calc(33.333% - 16px);
    }
}

@media (max-width: 475px) {
    #wens-prova-category .wp-block-column {
        flex: 1 1 calc(50% - 16px); /* Show 1 column per row */
        max-width: calc(50% - 16px);
    }
}



@media (max-width: 781px) {
    .wp-container-core-post-template-is-layout-1,
    .wp-container-core-post-template-is-layout-2 {
        grid-template-columns: repeat(2, minmax(0, 1fr))!important;
    }
}

@media (max-width: 475px) {
    .wp-container-core-post-template-is-layout-1,
    .wp-container-core-post-template-is-layout-2 {
        grid-template-columns: repeat(1, minmax(0, 1fr))!important;
    }
}
